<script setup lang="ts">const shop=useShop();const name=ref('');function add(){const n=name.value.trim();if(!n)return;if(shop.categories.some(c=>c.toLowerCase()===n.toLowerCase()))return shop.notify('That category already exists.','error');shop.categories.push(n);shop.saveCategories();name.value='';shop.notify('Demo category added.')}function remove(c:string){if(confirm(`Remove category label “${c}”? Products using it will keep their current category text.`)){shop.categories=shop.categories.filter(x=>x!==c);shop.saveCategories();shop.notify('Category label removed.')}} </script><template><div class="mx-auto w-full max-w-7xl px-4 sm:px-6 lg:px-8 py-10"><p class="text-xs font-bold uppercase tracking-[.2em] text-brand">Admin demo</p><h1 class="mt-2 text-4xl font-semibold tracking-tight">Categories<span class="text-brand">.</span></h1><form class="mt-7 flex max-w-xl gap-2" @submit.prevent="add"><input v-model="name" required class="min-w-0 flex-1 rounded-full border border-gray-200 px-4 py-3 text-sm" placeholder="New category name"><button class="rounded-full bg-ink px-5 text-xs font-bold uppercase tracking-wider text-white">Add</button></form><div class="mt-6 grid gap-3 sm:grid-cols-2 lg:grid-cols-3"><div v-for="c in shop.categories" :key="c" class="flex items-center justify-between rounded-xl border border-gray-100 p-4"><span class="text-sm font-semibold">{{ c }}</span><button class="text-xs text-red-600" @click="remove(c)">Remove</button></div></div><NuxtLink to="/admin" class="mt-6 inline-block text-xs font-semibold text-gray-500">← Back to dashboard</NuxtLink></div></template>
